const getWamParameterInfo=moduleId=>{const audioWorkletGlobalScope=globalThis;const normExp=(x,e)=>e===0?x:x**(1.5**-e);const denormExp=(x,e)=>e===0?x:x**(1.5**e);const normalize=(x,min,max,e=0)=>min===0&&max===1?normExp(x,e):normExp((x-min)/(max-min)||0,e);const denormalize=(x,min,max,e=0)=>min===0&&max===1?denormExp(x,e):denormExp(x,e)*(max-min)+min;const inRange=(x,min,max)=>x>=min&&x<=max;class WamParameterInfo{constructor(id,config={}){let{type:type,label:label,defaultValue:defaultValue,minValue:minValue,maxValue:maxValue,discreteStep:discreteStep,exponent:exponent,choices:choices,units:units}=config;if(type===undefined)type="float";if(label===undefined)label="";if(defaultValue===undefined)defaultValue=0;if(choices===undefined)choices=[];if(type==="boolean"||type==="choice"){discreteStep=1;minValue=0;if(choices.length)maxValue=choices.length-1;else maxValue=1}else{if(minValue===undefined)minValue=0;if(maxValue===undefined)maxValue=1;if(discreteStep===undefined)discreteStep=0;if(exponent===undefined)exponent=0;if(units===undefined)units=""}const errBase=`Param config error | ${id}: `;if(minValue>=maxValue)throw Error(errBase.concat("minValue must be less than maxValue"));if(!inRange(defaultValue,minValue,maxValue))throw Error(errBase.concat("defaultValue out of range"));if(discreteStep%1||discreteStep<0){throw Error(errBase.concat("discreteStep must be a non-negative integer"))}else if(discreteStep>0&&(minValue%1||maxValue%1||defaultValue%1)){throw Error(errBase.concat("non-zero discreteStep requires integer minValue, maxValue, and defaultValue"))}if(type==="choice"&&!choices.length){throw Error(errBase.concat("choice type parameter requires list of strings in choices"))}this.id=id;this.label=label;this.type=type;this.defaultValue=defaultValue;this.minValue=minValue;this.maxValue=maxValue;this.discreteStep=discreteStep;this.exponent=exponent;this.choices=choices;this.units=units}normalize(value){return normalize(value,this.minValue,this.maxValue,this.exponent)}denormalize(valueNorm){return denormalize(valueNorm,this.minValue,this.maxValue,this.exponent)}valueString(value){if(this.choices)return this.choices[value];if(this.units!=="")return`${value} ${this.units}`;return`${value}`}}if(audioWorkletGlobalScope.AudioWorkletProcessor){const ModuleScope=audioWorkletGlobalScope.webAudioModules.getModuleScope(moduleId);if(!ModuleScope.WamParameterInfo)ModuleScope.WamParameterInfo=WamParameterInfo}return WamParameterInfo};export default getWamParameterInfo;